        if (host == null) {
            return List.of();
        }
        List<ProtocolFrame> snapshots = new ArrayList<>();
        for (ProxySession session : host.sessions()) {
            try {
                ProtocolFrame snapshot = session.awaitSnapshot(timeoutMillis);
                if (snapshot != null) {
