    }

    /** Tear down: close the persistent state, unsubscribe the emitter, stop the batcher, drop the connection. */
    public void close() {
        ProxyHost host = proxyHost;
        if (host != null) {
            host.close();
            proxyHost = null;
        }
        state.close();
        emitter.destroy();
        batcher.close();
        connection = null;
    }
}

