  encodeEditingChanged,
  encodeEnvironment,
  encodeFocusChanged,
  encodeKeyDown,
  encodeKeyUp,
  encodeNavigate,
  encodeNavigateBack,
  encodePointerDown,
  encodePointerMove,
  encodePointerUp,
  encodeResync,
  encodeScroll,
  encodeTextChanged,
  encodeValueBits,
  encodeValueChanged,
  encodeWheel,
} from "./events";
import {
  FLAG_HOVER_ENTER,
  FLAG_HOVER_LEAVE,
  FLAG_POINTER_SECONDARY,
  LISTEN_EDITING,
  LISTEN_FOCUS,
  LISTEN_KEY_DOWN,
  LISTEN_KEY_UP,
  LISTEN_POINTER_DOWN,
  LISTEN_POINTER_MOVE,
  LISTEN_POINTER_UP,
  LISTEN_SCROLL,
