+const ALIGNMENT_CODES: Record<Alignment, number> = {
+  leading: 0,
+  center: 1,
+  trailing: 2,
+  topLeading: 0,
+  top: 3,
+  topTrailing: 7,
+  leadingCenter: 5,
+  trailingCenter: 6,
+  bottomLeading: 8,
