export interface StateStore {
  load(scope: string): Promise<Record<string, unknown>> | Record<string, unknown>;
  save(scope: string, key: string, value: unknown): void | Promise<void>;
  delete(scope: string, key: string): void | Promise<void>;
}

/** In-memory store (one map per session scope). */
export class MemoryStateStore implements StateStore {
  private readonly scopes = new Map<string, Map<string, unknown>>();

  load(scope: string): Record<string, unknown> {
    const entries = this.scopes.get(scope);
    return entries ? Object.fromEntries(entries) : {};
  }

  save(scope: string, key: string, value: unknown): void {
    let entries = this.scopes.get(scope);
    if (!entries) {
      entries = new Map();
      this.scopes.set(scope, entries);
    }
    entries.set(key, value);
  }

  delete(scope: string, key: string): void {
    this.scopes.get(scope)?.delete(key);
  }
}

import { effect, signal, type EffectRef, type WritableSignal } from "@pathland/signals";
import type { StateStore } from "./store";

/**
 * A persisted field holder. Declare it as a class field and call
 * `PersistentState.connect(this)` before mounting; the field name becomes the
 * store key unless an explicit key was supplied.
 */
export class State<T> {
  private bound: WritableSignal<T> | null = null;
  private fieldName = "";

  constructor(
    private readonly initial: T,
    private readonly explicitKey?: string,
  ) {}

  get key(): string {
    return this.explicitKey ?? this.fieldName;
  }

  get signal(): WritableSignal<T> {
    if (!this.bound) throw new Error(`State "${this.key}" is not connected`);
    return this.bound;
  }

  bind(state: PersistentState, fieldName: string): void {
    this.fieldName = fieldName;
    this.bound = state.state(this.explicitKey ?? fieldName, this.initial);
  }

  get(): T {
    return this.signal();
  }

  set(value: T): void {
    this.signal.set(value);
  }

  update(fn: (current: T) => T): void {
    this.signal.update(fn);
  }
}

/** Per-session connection between State fields and a StateStore. */
export class PersistentState {
  private readonly signals = new Map<string, WritableSignal<unknown>>();
  private readonly effects: EffectRef[] = [];

  constructor(
    private readonly store: StateStore,
    private readonly scope: string,
    private readonly preloaded: Record<string, unknown> = {},
  ) {}

  state<T>(key: string, initial: T): WritableSignal<T> {
    const existing = this.signals.get(key);
    if (existing) return existing as WritableSignal<T>;

    const loaded = Object.prototype.hasOwnProperty.call(this.preloaded, key)
      ? (this.preloaded[key] as T)
      : initial;
    const value = signal(loaded);
    this.signals.set(key, value as WritableSignal<unknown>);
    this.effects.push(
      effect(() => {
        try {
          const result = this.store.save(this.scope, key, value());
          if (result instanceof Promise) result.catch(() => undefined);
        } catch {
          // Persistence is best-effort; a UI update must not fail with the store.
        }
      }),
    );
    return value;
  }

  /** Bind every State field on `target` (recursively through nested view objects). */
  connect(target: object): void {
    this.connectObject(target, new WeakSet());
  }

  private connectObject(target: object, seen: WeakSet<object>): void {
    if (seen.has(target)) return;
    seen.add(target);
    for (const key of Object.keys(target)) {
      const value = (target as Record<string, unknown>)[key];
      if (value instanceof State) {
        value.bind(this, key);
      } else if (isTraversable(value)) {
        this.connectObject(value, seen);
      }
    }
  }

  close(): void {
    for (const ref of this.effects) ref.destroy();
    this.effects.length = 0;
    this.signals.clear();
  }
}

function isTraversable(value: unknown): value is object {
  if (value === null || typeof value !== "object") return false;
  if (Array.isArray(value) || value instanceof State) return false;
  if (value instanceof Map || value instanceof Set || value instanceof Date) return false;
  return true;
}

import { describe, expect, it } from "vitest";
import { MemoryStateStore, PersistentState, State } from "../src/index";

describe("@pathland/state", () => {
  it("loads a preloaded value before the initializer is used", () => {
    const state = new PersistentState(new MemoryStateStore(), "/w1", { count: 7 });
    expect(state.state("count", 0)()).toBe(7);
  });

  it("saves on change and scopes keys by session", () => {
    const store = new MemoryStateStore();
    const first = new PersistentState(store, "/w1");
    const count = first.state("count", 0);
    count.set(3);
    expect(store.load("/w1")).toEqual({ count: 3 });
    expect(store.load("/w2")).toEqual({});
  });

  it("auto-connects State fields by property name", () => {
    const store = new MemoryStateStore();
    store.save("/w1", "query", "hello");
    const view = new class {
      query = new State("");
      other = new State(1, "explicit");
    }();
    const state = new PersistentState(store, "/w1");
    state.connect(view);
    expect(view.query.signal()).toBe("hello");
    expect(view.query.key).toBe("query");
    expect(view.other.key).toBe("explicit");
  });

  it("persists explicit keys", () => {
    const store = new MemoryStateStore();
    const state = new PersistentState(store, "/w1");
    const value = state.state("theme", "light");
    value.set("dark");
    expect(store.load("/w1")).toEqual({ theme: "dark" });
  });

  it("stops saving after close", () => {
    const store = new MemoryStateStore();
    const state = new PersistentState(store, "/w1");
    const count = state.state("count", 0);
    state.close();
    count.set(9);
    expect(store.load("/w1")).toEqual({ count: 0 });
  });
});

