import type { ReadonlySignal, WritableSignal } from "@pathland/signals";

export interface ViewProperty {
  readonly property: number;
  readonly valueType: number;
  readonly value: number | string | readonly number[];
}

export type ViewModifier = ViewProperty;
export type ViewChildren = ViewElement[] | (() => ViewElement[]);

export interface ViewElement {
  readonly component: number;
  readonly props: readonly ViewProperty[];
  readonly mods: readonly ViewModifier[];
  readonly children: ViewChildren;
  readonly textSignal?: ReadonlySignal<string>;
  readonly textBinding?: WritableSignal<string>;
  readonly tapAction?: () => void;
  modifiers(...mods: ViewModifier[]): ViewElement;
}

export interface ElementOptions {
  component: number;
  props?: readonly ViewProperty[];
  children?: ViewChildren;
  textSignal?: ReadonlySignal<string>;
  textBinding?: WritableSignal<string>;
  tapAction?: () => void;
}

/** Create a retained view element. Modifiers are immutable chainable values. */
export function element(options: ElementOptions): ViewElement {
  const base: ViewElement = {
    component: options.component,
    props: options.props ?? [],
    mods: [],
    children: options.children ?? [],
    textSignal: options.textSignal,
    textBinding: options.textBinding,
    tapAction: options.tapAction,
    modifiers(...mods: ViewModifier[]): ViewElement {
      return {
        ...base,
        mods: [...base.mods, ...mods],
        modifiers: this.modifiers,
      };
    },
  };
  return base;
}

import {
  PROP_BACKGROUND_COLOR,
  PROP_BORDER_RADIUS,
  PROP_COLOR,
  PROP_FONT_SIZE,
  PROP_PADDING,
  VAL_COLOR,
  VAL_F32,
} from "@pathland/protocol";
import type { ViewModifier } from "./element";

export function padding(value: number): ViewModifier {
  return { property: PROP_PADDING, valueType: VAL_F32, value };
}

export function cornerRadius(value: number): ViewModifier {
  return { property: PROP_BORDER_RADIUS, valueType: VAL_F32, value };
}

export function fontSize(value: number): ViewModifier {
  return { property: PROP_FONT_SIZE, valueType: VAL_F32, value };
}

export function background(color: string | number): ViewModifier {
  return { property: PROP_BACKGROUND_COLOR, valueType: VAL_COLOR, value: colorBits(color) };
}

export function foregroundStyle(color: string | number): ViewModifier {
  return { property: PROP_COLOR, valueType: VAL_COLOR, value: colorBits(color) };
}

/** Pack a CSS-like color into the wire's sRGB `0xAARRGGBB`. */
export function colorBits(color: string | number): number {
  if (typeof color === "number") return color >>> 0;
  const text = color.trim();
  if (!text.startsWith("#")) throw new Error(`unsupported color "${color}"`);
  const hex = text.slice(1);
  if (hex.length === 3) {
    const r = parseInt(hex[0]! + hex[0]!, 16);
    const g = parseInt(hex[1]! + hex[1]!, 16);
    const b = parseInt(hex[2]! + hex[2]!, 16);
    return (0xff000000 | (r << 16) | (g << 8) | b) >>> 0;
  }
  if (hex.length === 6) return (0xff000000 | parseInt(hex, 16)) >>> 0;
  if (hex.length === 8) return parseInt(hex, 16) >>> 0;
  throw new Error(`unsupported color "${color}"`);
}

import {
  COMPONENT_BUTTON,
  COMPONENT_HSTACK,
  COMPONENT_IMAGE,
  COMPONENT_TEXT,
  COMPONENT_TEXT_FIELD,
  COMPONENT_VSTACK,
  COMPONENT_ZSTACK,
  LISTEN_POINTER_DOWN,
  LISTEN_POINTER_UP,
  PROP_ALIGNMENT,
  PROP_EVENT_LISTENERS,
  PROP_IMAGE_SOURCE,
  PROP_PROMPT,
  PROP_SPACING,
  VAL_F32,
  VAL_STRING,
  VAL_U32,
} from "@pathland/protocol";
import { InputSignal, type MaybeSignal, type WritableSignal } from "@pathland/signals";
import { element, type ViewChildren, type ViewElement, type ViewProperty } from "./element";

export type Alignment =
  | "leading"
  | "center"
  | "trailing"
  | "topLeading"
  | "top"
  | "topTrailing"
  | "leadingCenter"
  | "trailingCenter"
  | "bottomLeading"
  | "bottom"
  | "bottomTrailing";

const ALIGNMENT_CODES: Record<Alignment, number> = {
  leading: 0,
  center: 1,
  trailing: 2,
  topLeading: 0,
  top: 3,
  topTrailing: 7,
  leadingCenter: 5,
  trailingCenter: 6,
  bottomLeading: 8,
  bottom: 4,
  bottomTrailing: 2,
};

export interface VStackProps {
  spacing?: number;
  alignment?: Alignment;
}

export type HStackProps = VStackProps;
export type ZStackProps = Pick<VStackProps, "alignment">;

function stackProps(props: VStackProps): ViewProperty[] {
  const out: ViewProperty[] = [];
  if (props.spacing !== undefined) {
    out.push({ property: PROP_SPACING, valueType: VAL_F32, value: props.spacing });
  }
  if (props.alignment !== undefined) {
    out.push({ property: PROP_ALIGNMENT, valueType: VAL_F32, value: ALIGNMENT_CODES[props.alignment] });
  }
  return out;
}

function stack(
  component: number,
  props: VStackProps,
  children: ViewChildren,
): ViewElement {
  return element({ component, props: stackProps(props), children });
}

export function VStack(props: VStackProps, children: ViewChildren): ViewElement {
  return stack(COMPONENT_VSTACK, props, children);
}

export function HStack(props: HStackProps, children: ViewChildren): ViewElement {
  return stack(COMPONENT_HSTACK, props, children);
}

export function ZStack(props: ZStackProps, children: ViewChildren): ViewElement {
  return stack(COMPONENT_ZSTACK, props, children);
}

export interface TextProps {
  text: MaybeSignal<string>;
}

export function Text(props: TextProps): ViewElement {
  return element({ component: COMPONENT_TEXT, textSignal: InputSignal.from(props.text) });
}

export interface ImageProps {
  source: string;
}

export function Image(props: ImageProps): ViewElement {
  return element({
    component: COMPONENT_IMAGE,
    props: [{ property: PROP_IMAGE_SOURCE, valueType: VAL_STRING, value: props.source }],
  });
}

export interface TextFieldProps {
  placeholder?: string;
  text: WritableSignal<string>;
}

export function TextField(props: TextFieldProps): ViewElement {
  const viewProps: ViewProperty[] = [];
  if (props.placeholder !== undefined) {
    viewProps.push({ property: PROP_PROMPT, valueType: VAL_STRING, value: props.placeholder });
  }
  return element({ component: COMPONENT_TEXT_FIELD, props: viewProps, textBinding: props.text });
}

export interface ButtonProps {
  label: string;
  action?: () => void;
}

export function Button(props: ButtonProps): ViewElement {
  return element({
    component: COMPONENT_BUTTON,
    props: [
      {
        property: PROP_EVENT_LISTENERS,
        valueType: VAL_U32,
        value: LISTEN_POINTER_DOWN | LISTEN_POINTER_UP,
      },
    ],
    textSignal: InputSignal.from(props.label),
    tapAction: props.action,
  });
}

/**
 * Legacy TypeScript class decorator marker. Mounting stays explicit: the
 * application calls `body(props)` and passes the returned element to the
 * emitter. This is intentionally not tied to Angular DI or a compiler
 * transform.
 */
export function view<T extends object>(target: T): T {
  return target;
}

import type { WritableSignal } from "@pathland/signals";
import type { PersistentState } from "@pathland/state";

export interface AppPlatform {
  now(): number;
  random(): number;
}

export interface AppContext {
  state: PersistentState;
  platform: AppPlatform;
  route: WritableSignal<string>;
}

const stack: AppContext[] = [];

/** The context of the view currently being mounted or rendered. */
export function useAppContext(): AppContext {
  const context = stack[stack.length - 1];
  if (!context) throw new Error("useAppContext() called outside a Pathland mount");
  return context;
}

/** Run `fn` with `context` available to `useAppContext()`. */
export function withAppContext<T>(context: AppContext, fn: () => T): T {
  stack.push(context);
  try {
    return fn();
  } finally {
    stack.pop();
  }
}

