import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import {
  BatchWriter,
  CAT_PARAMETER,
  CAT_TREE,
  CMD_CREATE_NODE,
  CMD_SET_TEXT,
  COMPONENT_TEXT,
} from "@pathland/protocol";
import { loadSsrRenderer, renderPage, resolveBundleName } from "../src/index";

function textFrame(text: string): Uint8Array {
  const writer = new BatchWriter();
  writer.begin();
  writer.push(CAT_TREE, CMD_CREATE_NODE, 0, 1, COMPONENT_TEXT, 0);
  const offset = writer.string(text);
  writer.push(CAT_PARAMETER, CMD_SET_TEXT, 0, 1, offset, 0);
  return writer.end();
}

describe("@pathland/ssr", () => {
  it("renders a document and a fragment through the Rust wasm renderer", async () => {
    const wasmPath = fileURLToPath(new URL("../wasm/pathland_render_html.wasm", import.meta.url));
    const renderer = await loadSsrRenderer(readFileSync(wasmPath));
    const document = renderer.renderDocument(textFrame("Hello & <world>"), 1);
    expect(document).toContain("<!DOCTYPE html>");
    expect(document).toContain('data-pathland-id="1"');
    expect(document).toContain("Hello &amp; &lt;world&gt;");

    const fragment = renderer.renderFragment(textFrame("fragment"), 1);
    expect(fragment).not.toContain("<!DOCTYPE html>");
    expect(fragment).toContain("fragment");
  });

  it("does not leak output between consecutive renders", async () => {
    const wasmPath = fileURLToPath(new URL("../wasm/pathland_render_html.wasm", import.meta.url));
    const renderer = await loadSsrRenderer(readFileSync(wasmPath));
    expect(renderer.renderDocument(textFrame("first"), 1)).toContain("first");
    const second = renderer.renderDocument(textFrame("second"), 1);
    expect(second).toContain("second");
    expect(second).not.toContain("first");
  });

  it("injects the base, bundle, and SSR scope flags", () => {
    const html = renderPage("<html><body><main>x</main></body></html>", {
      base: "/_pathland",
      bundleName: "dom-renderer-abc.js",
      serviceWorker: true,
      ssrScoped: true,
    });
    expect(html).toContain('<html data-pathland-base="/_pathland" data-pathland-service-worker="true" data-pathland-ssr-scoped="true">');
    expect(html).toContain('<script src="/_pathland/dom-renderer-abc.js" defer></script></body>');
  });

  it("resolves the current bundle manifest", () => {
    const dir = fileURLToPath(new URL("../../ssr/wasm", import.meta.url));
    expect(resolveBundleName(dir)).toBe("dom-renderer.js");
  });
});

import type { ViewElement, AppContext } from "@pathland/view";

/** The application's root-view factory. A fresh root is created per session. */
export interface PathlandApp {
  newRoot(context: AppContext): ViewElement;
}

/** The transport seam: the session sends self-contained PLPL batches through this. */
export interface PathlandConnection {
  send(bytes: Uint8Array): void;
  isOpen(): boolean;
}

import {
  CAT_PARAMETER,
  CMD_SET_DESIGN_TOKEN,
  CMD_SET_PROPERTY,
  CMD_SET_TEXT,
  VAL_DESIGN_TOKEN,
  VAL_LIST,
  VAL_STRING,
  encodeBatch,
  parseBatch,
  type Opcode,
} from "@pathland/protocol";

const DEFAULT_FLUSH_INTERVAL_MS = 20;
const DEFAULT_MAX_BATCH_BYTES = 16 * 1024;

function rebase(op: Opcode, base: number): Opcode {
  let { a, b, c } = op;
  if (op.category === CAT_PARAMETER) {
    if (op.command === CMD_SET_TEXT) {
      b += base;
    } else if (op.command === CMD_SET_PROPERTY) {
      const valueType = b >>> 16;
      if (valueType === VAL_STRING || valueType === VAL_DESIGN_TOKEN || valueType === VAL_LIST) c += base;
    } else if (op.command === CMD_SET_DESIGN_TOKEN) {
      a += base;
      if ((b & 0xff) === VAL_STRING) c += base;
    }
  }
  return { category: op.category, command: op.command, flags: op.flags, a, b, c };
}

/** Coalesces session delta frames into one sequence-numbered PLPL batch. */
export class DeltaBatcher {
  private opcodes: Opcode[] = [];
  private strings: Uint8Array[] = [];
  private approxBytes = 0;
  private nextSequence = 1;
  private timer: ReturnType<typeof setTimeout> | null = null;
  private closed = false;

  constructor(
    private readonly sender: (bytes: Uint8Array) => void,
    private readonly flushIntervalMs = DEFAULT_FLUSH_INTERVAL_MS,
    private readonly maxBatchBytes = DEFAULT_MAX_BATCH_BYTES,
  ) {}

  append(frame: Uint8Array): void {
    if (this.closed) return;
    const batch = parseBatch(frame);
    if (batch.opcodes.length === 0) return;
    const base = this.strings.reduce((sum, part) => sum + part.length, 0);
    for (const op of batch.opcodes) this.opcodes.push(rebase(op, base));
    this.strings.push(batch.strings);
    this.approxBytes += batch.opcodes.length * 16 + batch.strings.length + 4;
    if (this.approxBytes >= this.maxBatchBytes) {
      this.flush();
    } else if (!this.timer) {
      this.timer = setTimeout(() => {
        this.timer = null;
        this.flush();
      }, this.flushIntervalMs);
      this.timer.unref?.();
    }
  }

  flush(): void {
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
    if (this.opcodes.length === 0) return;
    const strings = new Uint8Array(this.strings.reduce((sum, part) => sum + part.length, 0));
    let offset = 0;
    for (const part of this.strings) {
      strings.set(part, offset);
      offset += part.length;
    }
    const opcodes = this.opcodes;
    this.opcodes = [];
    this.strings = [];
    this.approxBytes = 0;
    this.sender(encodeBatch(opcodes, strings, this.nextSequence++));
  }

  close(): void {
    this.closed = true;
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
    this.opcodes = [];
    this.strings = [];
  }
}

import { randomUUID } from "node:crypto";
import { decodeEvents } from "@pathland/protocol";
import { Emitter, FrameOpcodeSink, InputDispatcher, type RenderResult } from "@pathland/engine";
import type { SsrRenderer } from "@pathland/ssr";
import { renderPage } from "@pathland/ssr";
import { signal } from "@pathland/signals";
import type { StateStore } from "@pathland/state";
import { PersistentState } from "@pathland/state";
import { withAppContext, type AppContext, type AppPlatform } from "@pathland/view";
import type { PathlandApp } from "./app";
import { DeltaBatcher } from "./batcher";
import type { PathlandConnection } from "./connection";

export interface PathlandSessionOptions {
  sessionId: string;
  app: PathlandApp;
  store: StateStore;
  env: { route: string; viewportWidth?: number; viewportHeight?: number };
  base: string;
  stateScope: string;
  ssrRenderer: SsrRenderer;
  bundleName: string;
}

export interface SessionRenderOptions {
  serviceWorker?: boolean;
  ssrScoped?: boolean;
}

/**
 * One application instance per client session. The mount frame is emitted in the
 * constructor but is only used for SSR; live deltas start after `connect`.
 */
export class PathlandSession {
  private readonly state: PersistentState;
  private readonly route;
  private readonly context: AppContext;
  private readonly sink: FrameOpcodeSink;
  private readonly emitter: Emitter;
  private readonly dispatcher: InputDispatcher;
  private readonly batcher: DeltaBatcher;
  private readonly rootId: number;
  private initialFrame: Uint8Array | null = null;
  private capturing = true;
  private connection: PathlandConnection | null = null;

  constructor(
    private readonly options: PathlandSessionOptions,
    preloaded: Record<string, unknown> = {},
  ) {
    this.state = new PersistentState(options.store, options.stateScope, preloaded);
    this.route = signal(options.env.route);
    const platform: AppPlatform = {
      now: () => Date.now(),
      random: () => Math.random(),
    };
    this.context = { state: this.state, platform, route: this.route };

    this.sink = new FrameOpcodeSink();
    this.sink.onFrame((frame) => this.handleFrame(frame));
    this.emitter = new Emitter(this.sink);
    const root = withAppContext(this.context, () => options.app.newRoot(this.context));
    const result: RenderResult = this.emitter.mount(root, this.context);
    this.capturing = false;
    this.rootId = result.rootId;
    this.dispatcher = new InputDispatcher(result, this.route);
    this.batcher = new DeltaBatcher((bytes) => this.send(bytes));
  }

  /** Load persisted state before mounting, then construct the session. */
  static async create(
    options: PathlandSessionOptions,
    preloaded?: Record<string, unknown>,
  ): Promise<PathlandSession> {
    const state = preloaded ?? ((await options.store.load(options.stateScope)) as Record<string, unknown>);
    return new PathlandSession(options, state ?? {});
  }

  async renderHtml(options: SessionRenderOptions = {}): Promise<string> {
    if (!this.initialFrame) throw new Error("session did not emit a mount frame");
    const document = this.options.ssrRenderer.renderDocument(this.initialFrame, this.rootId);
    return renderPage(document, {
      base: this.options.base,
      bundleName: this.options.bundleName,
      serviceWorker: options.serviceWorker,
      ssrScoped: options.ssrScoped,
    });
  }

  connect(connection: PathlandConnection): void {
    this.connection = connection;
  }

  applyEnvironment(env: { route: string; viewportWidth?: number; viewportHeight?: number }): void {
    this.route.set(env.route);
  }

  dispatch(bytes: Uint8Array): void {
    try {
      this.dispatcher.dispatch(decodeEvents(bytes));
    } catch {
      // Malformed events are dropped; a bad input must never tear down a session.
    }
  }

  resync(): void {
    this.emitter.renderFull();
    this.batcher.flush();
  }

  close(): void {
    this.state.close();
    this.emitter.destroy();
    this.batcher.close();
    this.connection = null;
  }

  private handleFrame(frame: Uint8Array): void {
    if (this.capturing) {
      this.initialFrame = frame;
      return;
    }
    if (this.connection?.isOpen()) this.batcher.append(frame);
  }

  private send(bytes: Uint8Array): void {
    const connection = this.connection;
    if (!connection?.isOpen()) {
      this.connection = null;
      return;
    }
    try {
      connection.send(bytes);
    } catch {
      this.connection = null;
    }
  }
}

export { randomUUID };

