import { randomUUID } from "node:crypto";
import { resolveBundleName, type SsrRenderer } from "@pathland/ssr";
import type { StateStore } from "@pathland/state";
import type { PathlandApp } from "./app";
import type { PathlandConnection } from "./connection";
import { PathlandSession } from "./session";

export interface PathlandRegistryOptions {
  app: PathlandApp;
  store: StateStore;
  ssrRenderer: SsrRenderer;
  base?: string;
  assetDir?: string;
  bundleName?: string;
}

interface PendingSession {
  stateScope: string;
  connection: PathlandConnection;
}

/**
 * Owns sessions 1:1 with connections. Session identity (`uiId`) is separate from
 * the persisted-state scope (`wid`). Sessions mount lazily on the first inbound
 * message so the live tree is seeded from the client's environment and scope.
 */
export class PathlandRegistry {
  private readonly app: PathlandApp;
  private readonly store: StateStore;
  private readonly ssrRenderer: SsrRenderer;
  private readonly bundleName: string;
  private readonly mountBase: string;
  private readonly sessions = new Map<string, PathlandSession>();
  private readonly pending = new Map<string, PendingSession>();
  private readonly queues = new Map<string, Promise<void>>();

  constructor(options: PathlandRegistryOptions) {
    this.app = options.app;
    this.store = options.store;
    this.ssrRenderer = options.ssrRenderer;
    this.bundleName = options.bundleName ?? resolveBundleName(options.assetDir);
    this.mountBase = (options.base ?? "/_pathland").replace(/\/+$/, "") || "/_pathland";
  }

  get base(): string {
    return this.mountBase;
  }

  get bundle(): string {
    return this.bundleName;
  }

  stateScope(windowId: string): string {
    return `/${windowId}`;
  }

  /** SSR uses a throwaway session; a real `wid` makes the document scope-aware. */
  async renderHtml(route: string, windowId?: string): Promise<string> {
    const scoped = typeof windowId === "string" && windowId.length > 0;
    const scope = this.stateScope(scoped ? windowId : randomUUID());
    const session = await PathlandSession.create({
      sessionId: randomUUID(),
      app: this.app,
      store: this.store,
      env: { route: route || "/" },
      base: this.mountBase,
      stateScope: scope,
      ssrRenderer: this.ssrRenderer,
      bundleName: this.bundleName,
    });
    try {
      return await session.renderHtml({ ssrScoped: scoped });
    } finally {
      session.close();
    }
  }

  open(uiId: string, windowId: string, connection: PathlandConnection): void {
    const existing = this.sessions.get(uiId);
    if (existing) {
      existing.close();
      this.sessions.delete(uiId);
    }
    this.pending.set(uiId, { stateScope: this.stateScope(windowId), connection });
  }

  environment(
    uiId: string,
    env: { route: string; viewportWidth?: number; viewportHeight?: number },
  ): Promise<void> {
    return this.enqueue(uiId, async () => {
      const session = await this.ensure(uiId, env);
      session.applyEnvironment(env);
    });
  }

  dispatch(uiId: string, bytes: Uint8Array): void {
    void this.enqueue(uiId, async () => {
      const session = await this.ensure(uiId, { route: "/" });
      session.dispatch(bytes);
    });
  }

  resync(uiId: string): void {
    void this.enqueue(uiId, async () => {
      const session = await this.ensure(uiId, { route: "/" });
      session.resync();
    });
  }

  close(uiId: string): void {
    void this.enqueue(uiId, async () => {
      this.pending.delete(uiId);
      const session = this.sessions.get(uiId);
      if (session) {
        session.close();
        this.sessions.delete(uiId);
      }
    });
  }

  shutdown(): void {
    for (const session of this.sessions.values()) session.close();
    this.sessions.clear();
    this.pending.clear();
  }

  activeSessions(): number {
    return this.sessions.size;
  }

  private async ensure(
    uiId: string,
    env: { route: string; viewportWidth?: number; viewportHeight?: number },
  ): Promise<PathlandSession> {
    const existing = this.sessions.get(uiId);
    if (existing) return existing;
    const pending = this.pending.get(uiId);
    const session = await PathlandSession.create({
      sessionId: uiId,
      app: this.app,
      store: this.store,
      env,
      base: this.mountBase,
      stateScope: pending?.stateScope ?? this.stateScope(uiId),
      ssrRenderer: this.ssrRenderer,
      bundleName: this.bundleName,
    });
    if (pending) {
      session.connect(pending.connection);
      this.pending.delete(uiId);
    }
    this.sessions.set(uiId, session);
    return session;
  }

  private enqueue(uiId: string, task: () => Promise<void>): Promise<void> {
    const previous = this.queues.get(uiId) ?? Promise.resolve();
    const next = previous.then(task, task);
    this.queues.set(uiId, next);
    void next
      .catch(() => undefined)
      .then(() => {
        if (this.queues.get(uiId) === next) this.queues.delete(uiId);
      });
    return next;
  }
}

import type { IncomingMessage, Server } from "node:http";
import type { Duplex } from "node:stream";
import { randomUUID } from "node:crypto";
import { decodeHostMessage, encodePong } from "@pathland/protocol";
import { WebSocket, WebSocketServer, type RawData } from "ws";
import type { PathlandConnection } from "./connection";
import type { PathlandRegistry } from "./registry";

export interface WebSocketAttachOptions {
  /** The reserved framework base; the endpoint is `${base}/ws`. */
  base?: string;
}

/** Attach the Pathland WebSocket endpoint to an HTTP server. */
export function attachPathlandWebSocket(
  server: Server,
  registry: PathlandRegistry,
  options: WebSocketAttachOptions = {},
): WebSocketServer {
  const base = (options.base ?? registry.base).replace(/\/+$/, "");
  const path = `${base}/ws`;
  const serverSockets = new WebSocketServer({ noServer: true });

  server.on("upgrade", (request: IncomingMessage, socket: Duplex, head: Buffer) => {
    const url = new URL(request.url ?? "/", "http://localhost");
    if (url.pathname !== path) return;
    serverSockets.handleUpgrade(request, socket, head, (ws) => {
      handleConnection(ws, url, registry);
    });
  });

  return serverSockets;
}

function handleConnection(ws: WebSocket, url: URL, registry: PathlandRegistry): void {
  const uiId = randomUUID();
  const windowId = url.searchParams.get("wid") ?? randomUUID();
  const connection: PathlandConnection = {
    send(bytes) {
      if (ws.readyState === WebSocket.OPEN) ws.send(bytes, { binary: true });
    },
    isOpen() {
      return ws.readyState === WebSocket.OPEN;
    },
  };
  registry.open(uiId, windowId, connection);

  ws.on("message", (data: RawData, isBinary: boolean) => {
    if (!isBinary) return;
    let bytes: Uint8Array;
    try {
      bytes = toBytes(data);
    } catch {
      return;
    }
    let message;
    try {
      message = decodeHostMessage(bytes);
    } catch {
      return;
    }
    switch (message.type) {
      case "environment":
        void registry.environment(uiId, message.env);
        break;
      case "resync":
        registry.resync(uiId);
        break;
      case "ping":
        connection.send(encodePong());
        break;
      case "pong":
        break;
      case "events":
        registry.dispatch(uiId, bytes);
        break;
    }
  });

  ws.on("close", () => registry.close(uiId));
  ws.on("error", () => undefined);
}

function toBytes(data: RawData): Uint8Array {
  if (data instanceof ArrayBuffer) return new Uint8Array(data);
  if (Array.isArray(data)) {
    const total = data.reduce((sum, part) => sum + part.byteLength, 0);
    const out = new Uint8Array(total);
    let offset = 0;
    for (const part of data) {
      out.set(new Uint8Array(part.buffer, part.byteOffset, part.byteLength), offset);
      offset += part.byteLength;
    }
    return out;
  }
  return new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
}

import express, { type RequestHandler, type Router } from "express";
import type { Server } from "node:http";
import {
  PathlandRegistry,
  type PathlandRegistryOptions,
} from "./registry";
import { attachPathlandWebSocket } from "./ws";

export interface PathlandExpressOptions extends PathlandRegistryOptions {
  /** Static directory containing the content-hashed DOM client and manifest. */
  assetDir?: string;
}

export interface PathlandExpress {
  registry: PathlandRegistry;
  router: Router;
  attach(server: Server): void;
}

/**
 * Express adapter: serve the DOM client assets and SSR every HTML GET; attach
 * the WebSocket endpoint with `attach(httpServer)`.
 */
export function pathlandExpress(options: PathlandExpressOptions): PathlandExpress {
  const registry = new PathlandRegistry(options);
  const router = express.Router();
  const base = registry.base;

  if (options.assetDir) {
    router.use(base, express.static(options.assetDir));
  }

  const ssr: RequestHandler = async (request, response, next) => {
    if (request.method !== "GET" || !request.accepts("html")) {
      next();
      return;
    }
    if (request.path === base || request.path.startsWith(`${base}/`)) {
      next();
      return;
    }
    try {
      const wid = typeof request.query.wid === "string" ? request.query.wid : undefined;
      const html = await registry.renderHtml(request.path || "/", wid);
      response.type("html").send(html);
    } catch (error) {
      next(error);
    }
  };
  router.use(ssr);

  return {
    registry,
    router,
    attach(server: Server) {
      attachPathlandWebSocket(server, registry, { base });
    },
  };
}

import "reflect-metadata";
import {
  Injectable,
  SetMetadata,
  type CallHandler,
  type ExecutionContext,
  type NestInterceptor,
} from "@nestjs/common";
import type { Observable } from "rxjs";
import { of } from "rxjs";
import type { PathlandRegistry } from "./registry";

export const PATHLAND_VIEW = "pathland:view";

/** Mark a Nest controller/route as Pathland-rendered. */
export function PathlandView(): MethodDecorator & ClassDecorator {
  return (target: object, key?: string | symbol, descriptor?: PropertyDescriptor) => {
    SetMetadata(PATHLAND_VIEW, true)(target, key as string, descriptor as PropertyDescriptor);
  };
}

interface NestRequest {
  path: string;
  query?: Record<string, unknown>;
}

interface NestResponse {
  type(value: string): void;
}

/** Serve SSR HTML for routes marked with `@PathlandView()`. */
@Injectable()
export class PathlandInterceptor implements NestInterceptor {
  constructor(private readonly registry: PathlandRegistry) {}

  async intercept(context: ExecutionContext, next: CallHandler): Promise<Observable<unknown>> {
    if (context.getType() !== "http") return next.handle();
    const marked =
      Reflect.getMetadata(PATHLAND_VIEW, context.getHandler()) ||
      Reflect.getMetadata(PATHLAND_VIEW, context.getClass());
    if (!marked) return next.handle();

    const http = context.switchToHttp();
    const request = http.getRequest<NestRequest>();
    const response = http.getResponse<NestResponse>();
    const wid = typeof request.query?.wid === "string" ? request.query.wid : undefined;
    const html = await this.registry.renderHtml(request.path || "/", wid);
    response.type("html");
    return of(html);
  }
}

export * from "./app";
export * from "./connection";
export * from "./batcher";
export * from "./session";
export * from "./registry";
export * from "./ws";
export * from "./express";

