                .modifiers(
                        padding(24),
                        background(MusicPlayerView.SIDEBAR_BG),
                        frame(f -> f.width(MusicPlayerView.SIDEBAR_WIDTH).height(Commands.Size.FILL)))
                .children(children.toArray(new View[0]));
    }

    /**
