+
+export interface SliderProps {
+  value: WritableSignal<number>;
+  min?: number;
+  max?: number;
+}
+
+export function Slider(props: SliderProps): ViewElement {
+  const min = props.min ?? 0;
+  const max = props.max ?? 1;
+  return element({
